---@class PagleNS
local ns = select(2, ...)

-- The bindings' closed books (logic/Bindings.lua's swatches, ADR 0015), added to ns.ATLASES by name: the shop's
-- preview of a binding (wallet-and-shop.md › UI). Core ships every binding's art, the Modules' earned ones too
-- (SHOP-R25), under media/books/. Copied from the kits' atlases: Bindings from the Ledger art kit's Atlas.lua
-- (generated by its art/ledger/generate.py), Bindings2 from the shop expansion kit's Bindings board, Covers2 from
-- its covers (`goods.json`) and Bindings3 from the Curio Shop's round-two kit's (its `goods.json`). Rectangles are in texels, `scale` texels per UI unit; `box` is the drawn closed book
-- inside its sprite in UI units (x, y from the sprite's top left, then w, h), the rest being its shadow. The textures
-- are BLP (DXT5) with mipmaps.

local DIR = "Interface\\AddOns\\Pagle\\media\\books\\"

ns.ATLASES = ns.ATLASES or {}

-- A grid of sprites of one size, by name: each its x and y in texels.
---@param at table<string, integer[]>
---@param w integer
---@param h integer
---@param box number[]
---@return table<string, PagleAtlasSprite>
local function grid(at, w, h, box)
	local sprites = {}
	for name, xy in pairs(at) do
		sprites[name] = { x = xy[1], y = xy[2], w = w, h = h, box = box }
	end
	return sprites
end

